import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    m = len(coords)
    sink = m - 1

    adj = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        fwd = [v, cap, cost, len(adj[v])]
        rev = [u, 0, -cost, len(adj[u])]
        adj[u].append(fwd)
        adj[v].append(rev)

    for i in range(sink):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m):
        pu = pot[u]
        if pu == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    flow = 0
    min_cost = 0

    while flow < k:
        dist = [INF] * m
        dist[0] = 0
        prev_u = [-1] * m
        prev_e = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        prev_u[v] = u
                        prev_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for v in range(m):
            if dist[v] < INF:
                pot[v] += dist[v]

        if pot[sink] >= 0:
            break

        add_f = k - flow
        v = sink
        while v != 0:
            u = prev_u[v]
            cap = adj[u][prev_e[v]][1]
            if cap < add_f:
                add_f = cap
            v = u

        v = sink
        while v != 0:
            u = prev_u[v]
            edge = adj[u][prev_e[v]]
            edge[1] -= add_f
            adj[v][edge[3]][1] += add_f
            v = u

        flow += add_f
        min_cost += add_f * pot[sink]

    return -min_cost
